/* ===== HOME PHOTO CIRCLE — match height of name-to-social-icons block ===== */
function syncHomeImgSize() {
  const content = document.querySelector('.home-content');
  const frame = document.querySelector('.home-img-frame');
  if (!content || !frame) return;
  if (window.innerWidth <= 900) { frame.style.width = ''; frame.style.height = ''; return; }
  const h = content.offsetHeight;
  frame.style.width = h + 'px';
  frame.style.height = h + 'px';
}
window.addEventListener('load', syncHomeImgSize);
window.addEventListener('resize', syncHomeImgSize);
document.addEventListener('DOMContentLoaded', syncHomeImgSize);

function syncAboutImgSize() {
  const heading = document.getElementById('aboutHeading');
  const tabs = document.getElementById('aboutTabs');
  const box = document.querySelector('.about-img-box');
  const col = document.querySelector('.about-img-col');
  if (!heading || !tabs || !box || !col) return;
  if (window.innerWidth <= 900) { box.style.height = ''; return; }
  const topOffset = parseFloat(getComputedStyle(col).top) || 0;
  const headingTop = heading.getBoundingClientRect().top;
  const tabsBottom = tabs.getBoundingClientRect().bottom;
  const h = (tabsBottom - headingTop) - topOffset;
  if (h > 0) box.style.height = h + 'px';
}
window.addEventListener('load', syncAboutImgSize);
window.addEventListener('resize', syncAboutImgSize);
document.addEventListener('DOMContentLoaded', syncAboutImgSize);

/* ===== COLOMBO LIVE CLOCK ===== */
function updateInfoClock() {
  const card = document.querySelector('.info-clock-card');
  if (!card) return;
  const tz = card.getAttribute('data-tz') || 'Asia/Colombo';

  let now;
  try {
    now = new Date(new Date().toLocaleString('en-US', { timeZone: tz }));
  } catch (e) {
    return;
  }

  const hours = now.getHours();
  const minutes = now.getMinutes();
  const seconds = now.getSeconds();
  const ampm = hours >= 12 ? 'PM' : 'AM';
  const hour12 = hours % 12 === 0 ? 12 : hours % 12;

  const hm = card.querySelector('.info-clock-hm');
  const ap = card.querySelector('.info-clock-ampm');
  const dt = card.querySelector('.info-clock-date');
  if (hm) hm.textContent = `${String(hour12).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;
  if (ap) ap.textContent = ampm;
  if (dt) dt.textContent = now.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });

  const hourDeg = (hours % 12) * 30 + minutes * 0.5;
  const minDeg = minutes * 6 + seconds * 0.1;
  const secDeg = seconds * 6;

  const hourHand = card.querySelector('.info-clock-hour');
  const minHand = card.querySelector('.info-clock-min');
  const secHand = card.querySelector('.info-clock-sec');
  if (hourHand) hourHand.setAttribute('transform', `rotate(${hourDeg} 50 50)`);
  if (minHand) minHand.setAttribute('transform', `rotate(${minDeg} 50 50)`);
  if (secHand) secHand.setAttribute('transform', `rotate(${secDeg} 50 50)`);
}
updateInfoClock();
setInterval(updateInfoClock, 1000);

